type syntax = Ocaml | Mermaid | Markdown

let generator_name = "CandaceCodegen"

(* Build-time configuration shared by this compiler's generated outputs. The
   development version identifies this generator, not a release or source commit.
   Keep the required markers and comment-safe, single-line form documented in
   the interface when editing this value. *)
let text =
  "Code generated by " ^ generator_name ^
  " v0.1.0-dev; the _cgen suffix marks generated files. DO NOT EDIT."

let render = function
  | Ocaml -> "(* " ^ text ^ " *)\n"
  | Mermaid -> "%% " ^ text ^ "\n"
  | Markdown -> "<!-- " ^ text ^ " -->\n"
